-- =============================================================================
-- University of Nigeria, Nsukka -- Faculty of Agriculture
-- Department of Crop Science -- five-year B.Agric degree programme
-- =============================================================================
-- SOURCE: the department's own official page,
--   https://cropscience.unn.edu.ng/course-modules/
-- This is real HTML text published by the department, not a photographed
-- handbook page, so the course codes, titles and units are read directly
-- rather than transcribed from an image.
--
-- VERIFICATION: the page prints a "Total" for each semester. Every one of the
-- 10 totals was recomputed from the individual unit values and matches:
-- 16, 15, 17, 23, 17, 20, 15, 16, 18, 18.
--
-- FIFTH YEAR: the programme splits into three options -- Crop Production, Crop
-- Protection and Horticulture. A student follows one of them. The rows below
-- are the UNION of the three option tables, de-duplicated by course code, with
-- every fifth-year row flagged is_elective = true and its description naming
-- which options list it. Inserting all three tables verbatim would have
-- produced the same course code three times over.
--
-- KNOWN ERRORS IN THE SOURCE PAGE (transcribed faithfully, never silently
-- "corrected", and each one called out in the affected row's description):
--   * the Horticulture table lists CSC 531 titled "Field Crops", duplicating
--     CSC 521, where the other two options title CSC 531 "Plant Protection";
--   * the Crop Protection table lists "ANS 541 Soil Physic" -- an Animal
--     Science code -- where the others list "SSC 541 Soil Physics";
--   * the Crop Protection table puts "Soil and Plant Analysis" under SSC 563,
--     which is Soil Fertility everywhere else on the same page;
--   * the final-year project appears as CSC 552, CSC 592 and CSC 572 in three
--     different places on the page;
--   * CSC 512 is 1 unit in every option table but 2 units in the description
--     section; the tables are used, since they are what the totals reconcile
--     against;
--   * first year first semester prints the code as "MTH III" rather than
--     "MTH 111".
-- The page also describes CSC 551 and CSC 561, which appear in no option
-- table; they are therefore not loaded as programme courses.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Crop Science';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name, is_elective)
values
  ('AGR 101', 'Biomathematics', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CHM 101', 'Basic Principles of Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 2, 'Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear Chemistry: Radioactivity and its practical applications.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CHM 171', 'Basic Practical Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 2, 'Laboratory operations: theory and practice of simple volumetric and quantitative analysis, simple organic preparations, functional group reactions, and physical chemistry determinations.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('BIO 151', 'General Biology I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 3, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('MTH 111', 'General Mathematics', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 3, 'Elementary set theory, subsets, union, intersection, complements. Venn diagrams, real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand diagram, De Moivre''s theorem, nth roots of unity. The source page prints this code as "MTH III" (three capital letter I characters); it is recorded here as MTH 111, the code that title corresponds to.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('GSP 101', 'Communication in English I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('GSP 111', 'Use of Library and Study Skills', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'first', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('AGR 102', 'Agric. Physics', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 4, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CHM 112', 'Basic Principles of Chemistry II', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 2, 'Gas laws and kinetic theory: kinetic theory of gases, elementary derivation and deduction of gas laws, molecular speeds, deviations from ideal behaviour, van der Waals modification, and gas liquefaction. Phase equilibrium and solutions: phase transitions and phase equilibria in one-component systems; ideal solutions, Raoult''s law, Henry''s law, real solutions, and colligative properties. Thermodynamics and kinetics: aspects of the first law of thermodynamics, thermochemistry, entropy, free energy, and spontaneous changes; ionic equilibria, acids, bases, indicators, and buffers; elementary chemical kinetics.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CHM 122', 'Basic Principles of Organic Chemistry III', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 2, 'Structure and classification: historical survey of organic chemistry, IUPAC nomenclature, classification of organic compounds, homologous series, elemental analysis, molecular formulas, and structural isomerism. Bonding and reactivity: isolation and purification methods, functional group concepts, resonance, and aromaticity. Functional groups: saturated and unsaturated hydrocarbons, cyclic hydrocarbons, alcohols, alkyl halides, ethers, aldehydes, ketones, carboxylic acids, amines, and aromatic compounds. Stereochemistry and lipids: introduction to oils, fats, and stereoisomerism.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('BIO 152', 'General Biology II', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 3, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('BIO 153', 'General Biology (Practical)', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('GSP 102', 'Communication in English II', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '100 Level', 'second', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CSC 211', 'Principles of Forestry', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '200 Level', 'first', 2, 'Renewable natural resources - availability, distribution and potential. The important forest trees and wildlife (with emphasis on Nigerian species). Classification, morphology and distribution of important forestry trees. Forest and game reserves in Nigeria. Silviculture and afforestation characteristics of major timber and their uses. Felling and log transportation.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CSC 221', 'Crop Anatomy, Taxonomy and Physiology', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '200 Level', 'first', 2, 'Origin and introduction to the taxonomy of cultivated plants with particular reference to tropical crops. Cell biology. Pollination, seed dormancy and seed germination. Morphology and reproduction of important tropical crops. Quantitative aspects of plant crop growth. Nutritional and environmental influences on crop growth, development and yield. Regulation of growth and development, biosynthesis, storage and mobilization of harvestable reserves in crops.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('AGR 201', 'General Agriculture', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '200 Level', 'first', 3, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
