  ('CED 341', 'Introduction to Entrepreneurship I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '300 Level', 'first', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
