  ('CED 342', 'Introduction to Entrepreneurship II', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '300 Level', 'second', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('ABE 306', 'Introduction to Farm Machinery', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '300 Level', 'second', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CSC 421', 'Crop Production Techniques', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'first', 4, 'Crops covered are legumes, cereals, roots, tubers and horticultural crops. Layout of plots, nursery bed construction; ridge and mound construction with hoes. Direct planting, rice nursery management and transplanting. Manures, fertilization, weeding, use and care of spray equipment. Estimation of yield of grains and cereals, dry matter content, starch, protein and oil content. Field management of vegetable gardens, fruit trees and plantation crops. Harvesting and handling of produce.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('CSC 431', 'Crop Protection and Pest Control', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'first', 2, 'Field identification of crop diseases and pests. Collection and classification of crop pathogens and pests. Pest control techniques - chemical, cultural, biological and others.', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('AGR 401', 'Agricultural Products Storage', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'first', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
