  ('ANS 471', 'Animal Husbandry Techniques', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'first', 3, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('AGR 402', 'Farm Work Project and Report Writing', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'second', 6, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
  ('AEX 412', 'Extension Practices', 'University of Nigeria, Nsukka', 'Faculty of Agriculture', 'Crop Science', '400 Level', 'second', 2, '', '[]'::jsonb, 'UNN Department of Crop Science official website', false),
